pr.solution:
def embed(pixels, bits):
    out = list(pixels)
    for i, b in enumerate(bits):
        out[i] = (out[i] & ~1) | int(b)
    return out

def extract(pixels, n):
    return ''.join(str(p & 1) for p in pixels[:n])
